import sys,types,tarfile,random,json,pathlib,tempfile
import a7.types as current
root=pathlib.Path('/home/cx89/Projects/pl-dev/a7-py');baseline=types.ModuleType('baseline_a7_types');sys.modules[baseline.__name__]=baseline
with tarfile.open(root/'tmp/v1-core-implementation-tycajqwt/baseline-source.tar.gz') as archive:
 exec(compile(archive.extractfile('a7/types.py').read(),'baseline/a7/types.py','exec'),baseline.__dict__)
rng=random.Random(714)
def descriptor(depth):
 if not depth:return ('primitive',rng.choice(['i32','string','f64','bool']))
 tag=rng.choice(['array','slice','pointer','reference','function','struct','generic','parameter','set','named'])
 if tag=='array':return(tag,descriptor(depth-1),rng.randrange(5))
 if tag in ['slice','pointer','reference']:return(tag,descriptor(depth-1))
 if tag=='function':return(tag,[descriptor(depth-1) for _ in range(rng.randrange(3))],descriptor(depth-1) if rng.randrange(2) else None,bool(rng.randrange(2)),descriptor(depth-1) if rng.randrange(2) else None)
 if tag in ['struct','generic','set']:return(tag,[descriptor(depth-1) for _ in range(rng.randrange(3))])
 if tag=='parameter':return(tag,[descriptor(depth-1) for _ in range(rng.randrange(3))])
 return(tag,rng.choice(['Node','Tree','Table']))
def build(mod,d):
 tag=d[0]
 if tag=='primitive':return mod.PrimitiveType(d[1])
 if tag=='array':return mod.ArrayType(build(mod,d[1]),d[2])
 if tag in ['slice','pointer','reference']:return getattr(mod,{'slice':'SliceType','pointer':'PointerType','reference':'ReferenceType'}[tag])(build(mod,d[1]))
 if tag=='function':return mod.FunctionType([build(mod,x) for x in d[1]],build(mod,d[2]) if d[2] else None,d[3],build(mod,d[4]) if d[4] else None)
 if tag=='struct':return mod.StructType(fields=[mod.StructField('f'+str(i),build(mod,x)) for i,x in enumerate(d[1])])
 if tag=='generic':return mod.GenericInstanceType('Box',[build(mod,x) for x in d[1]])
 if tag=='set':return mod.TypeSet(frozenset(build(mod,x) for x in d[1]))
 if tag=='parameter':return mod.GenericParamType('T',mod.TypeSet(frozenset(build(mod,x) for x in d[1])))
 return mod.StructType(d[1],generic_params=['T'])
failures=[]
for i in range(300):
 d=descriptor(4);a,b=build(baseline,d),build(current,d)
 if str(a)!=str(b) or hash(a)!=hash(b) or repr(a)!=repr(b):failures.append({'case':i,'descriptor':d,'old':str(a),'new':str(b)})
for mod in [baseline,current]:
 deep=mod.I32
 for _ in range(1500):deep=mod.SliceType(deep)
 limit=sys.getrecursionlimit()
 try:
  sys.setrecursionlimit(100)
  try: result={'length':len(str(deep))}
  except RecursionError:result={'error':'RecursionError'}
 finally:sys.setrecursionlimit(limit)
 print(mod.__name__,result)
out=pathlib.Path(tempfile.mkdtemp(prefix='a7-type-display-evidence-'));(out/'results.json').write_text(json.dumps({'seed':714,'cases':300,'failures':failures},indent=2));print(json.dumps({'cases':300,'mismatches':len(failures),'evidence':str(out)}))
